#!/usr/bin/env python3
"""microbiome/cultured_isolate_wgs_real — auto-generated run.py (archetype=microbiome_pipeline).

第一版只实现 simulate 模式:从 stdin/args 拿 inputs,产合理合成数据 JSON。
真实现路径(simulate=False)留 stub:返回 not-implemented + 提示。

输入契约:
  stdin JSON,字段按 SKILL.md 的 inputs 段;simulate 默认 true。
  CLI 兜底:--simulate / 各位置参数。

输出:
  stdout JSON;失败时也写 JSON {"ok": false, "error": "..."} 而非裸 traceback。
"""
import json
import sys

ARCHETYPE = "microbiome_pipeline"
BRAIN = "microbiome"
SKILL = "cultured_isolate_wgs_real"

def simulate(payload):
    """auto-generated by regen_simulate.py — outputs schema 来自 SKILL.md."""
    import copy
    import random
    random.seed(int(payload.get("seed", 42)) if isinstance(payload, dict) else 42)
    out = copy.deepcopy({'skill_id': 'cultured_isolate_wgs_real', 'n_samples': 0, 'taxonomy_table': '', 'diversity_metrics': {'shannon': 0.0, 'observed_otus': 0}, 'diagnostics': {'brain': 'microbiome', 'archetype': 'microbiome_pipeline'}})
    if isinstance(out, dict):
        out.setdefault("diagnostics", {})
        if isinstance(out["diagnostics"], dict):
            out["diagnostics"].update({
                "simulated": True,
                "archetype": ARCHETYPE,
                "brain": BRAIN,
                "skill": SKILL,
            })
        if "skill_id" in out and not out["skill_id"]:
            out["skill_id"] = SKILL
    return out

def real(payload):
    """Cultured isolate WGS 单菌 taxonomy via kraken2 + bracken。host_env=praxis-microbiome-kraken。
    输入:fastq_1 + fastq_2(paired) 或 fastq(single) / db_path / out_dir
    输出:taxonomy_table / n_samples / diversity_metrics
    """
    import os as _os
    import tempfile as _tempfile
    import time as _time
    try:
        from brains._common.lib.run_tool import run_tool
    except ImportError:
        import sys as _sys
        _sys.path.insert(0, "/home/zkyd/data1/mzy/praxis2-brains")
        from _common.lib.run_tool import run_tool  # noqa: F401
    fq1 = payload.get("fastq_1") or payload.get("fastq")
    fq2 = payload.get("fastq_2")
    db = payload.get("db_path") or payload.get("kraken_db")
    out_dir = payload.get("out_dir") or _tempfile.mkdtemp(prefix="kraken2_")
    diagnostics = {"brain": BRAIN, "skill": SKILL, "archetype": ARCHETYPE,
                   "tool": "kraken2+bracken", "out_dir": out_dir}
    if _os.environ.get("PRAXIS_SKILL_DRY_HOST") == "1":
        return {"ok": True, "skill_id": SKILL, "n_samples": 0,
                "taxonomy_table": "", "diversity_metrics": {"shannon": 0.0, "observed_otus": 0},
                "diagnostics": {**diagnostics, "dry": True}}
    if not fq1 or not _os.path.isfile(fq1):
        return {"ok": False, "error": f"fastq_1 不存在: {fq1!r}", "diagnostics": diagnostics}
    if not db:
        return {"ok": False, "error": "需要 db_path(kraken2 DB)", "diagnostics": diagnostics}
    report = _os.path.join(out_dir, "kraken.report")
    out_kr = _os.path.join(out_dir, "kraken.out")
    cmd = ["kraken2", "--db", db, "--threads", str(payload.get("threads", 8)),
           "--report", report, "--output", out_kr]
    if fq2 and _os.path.isfile(fq2):
        cmd += ["--paired", fq1, fq2]
    else:
        cmd += [fq1]
    t0 = _time.time()
    r = run_tool(cmd, timeout=int(payload.get("timeout_s", 3600)))
    diagnostics["subprocess"] = {"wall_sec": r.get("wall_sec"), "rc": r.get("returncode")}
    if not r["ok"]:
        return {"ok": False, "error": r.get("error", "kraken2 失败"),
                "stderr": r.get("stderr", "")[-300:], "diagnostics": diagnostics}
    # Bracken refine(species level)
    bracken_out = _os.path.join(out_dir, "bracken.tsv")
    rb = run_tool(["bracken", "-d", db, "-i", report, "-o", bracken_out,
                   "-r", str(payload.get("read_len", 150)), "-l", "S"],
                  timeout=600)
    diagnostics["bracken"] = {"wall_sec": rb.get("wall_sec"), "rc": rb.get("returncode")}
    # 解析 shannon
    shannon, n_taxa = 0.0, 0
    if _os.path.isfile(bracken_out):
        try:
            import math
            with open(bracken_out) as fh:
                next(fh, None)  # header
                fracs = []
                for ln in fh:
                    parts = ln.strip().split("\t")
                    if len(parts) >= 7:
                        try: fracs.append(float(parts[6]))
                        except ValueError: pass
                n_taxa = len(fracs)
                total = sum(fracs) or 1.0
                ps = [f/total for f in fracs if f > 0]
                shannon = -sum(p*math.log(p) for p in ps)
        except Exception:
            pass
    return {"ok": True, "skill_id": SKILL, "n_samples": 1,
            "taxonomy_table": bracken_out if _os.path.isfile(bracken_out) else report,
            "diversity_metrics": {"shannon": round(shannon, 3), "observed_otus": n_taxa},
            "runtime_sec": round(_time.time() - t0, 2), "diagnostics": diagnostics}

def main():
    # stdin 优先(SkillExecTool 走 stdin)
    payload = {}
    if not sys.stdin.isatty():
        try:
            payload = json.load(sys.stdin)
            if not isinstance(payload, dict):
                payload = {}
        except json.JSONDecodeError:
            payload = {}
    if not payload:
        # 简易 CLI 兜底
        import argparse
        ap = argparse.ArgumentParser()
        ap.add_argument("--simulate", action="store_true", default=True)
        ap.add_argument("--seed", type=int, default=42)
        args, _ = ap.parse_known_args()
        payload = {"simulate": args.simulate, "seed": args.seed}

    simulate_mode = bool(payload.get("simulate", True))
    try:
        out = simulate(payload) if simulate_mode else real(payload)
    except Exception as e:
        out = {"ok": False, "error": f"run.py 内部错误: {e!r}"}

    if isinstance(out, dict):
        out.setdefault("diagnostics", {})
        if isinstance(out["diagnostics"], dict):
            out["diagnostics"].update({"archetype": ARCHETYPE, "brain": BRAIN, "skill": SKILL})
    json.dump(out, sys.stdout, ensure_ascii=False)
    sys.stdout.write("\n")
    return 0

if __name__ == "__main__":
    sys.exit(main())
